import {beginAction,endAction,notify,noteRequest} from './action-feedback.js?v=1';
import {draftPriority,reviewGroups,latestVersions,ruleText,deadlineText,renderRuleBuilder,readRule,alterRule,renderDeadlineBuilder,readDeadline} from './reviewer-controls.js?v=5';
import {captureFormDrafts,restoreFormDrafts,captureView,restoreView} from './ui-continuity.js?v=3';
import {checklistGuide,reviewState,renderGuide,renderVerificationSummary} from './checklist-guide.js?v=11';
import {renderVerificationForm} from './verification-form.js?v=1';
import {factLabel} from './checklist-facts.js?v=7';
const vnDate=d=>d?String(d).slice(0,10).split('-').reverse().join('/'):'';
const DATE_LABELS={LEGAL:'Hạn pháp lý',EXPECTED:'Ngày dự kiến hoàn thành',REMINDER:'Ngày nhắc'};
const reminderOf=t=>t.pilot?t.progress?.review?.reminderDate:t.reviewJson?.reminderDate;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sourceImport=false;
let adminGroup=null,adminFilter='pending',adminQuery='';
const assessmentDates=new Map();
let pendingTask=null,mode='',filter='all',query='',group='all',sort='due',pageSize=20,calendarOffset=0,listScroll=0,calendarOpen=null;
// Filters survive opening a task, switching screens and reloads (per company, this browser only).
const viewKey=()=>'limi-tasks:'+h.company()?.id;
function saveView(){try{sessionStorage.setItem(viewKey(),JSON.stringify({filter,query,group,sort,pageSize,page}));}catch{}}
function loadView(){try{const v=JSON.parse(sessionStorage.getItem(viewKey())||'{}');filter=['all','todo','need','done'].includes(v.filter)?v.filter:'all';query=typeof v.query==='string'?v.query:'';group=typeof v.group==='string'?v.group:'all';sort=['due','title','recent'].includes(v.sort)?v.sort:'due';pageSize=[10,20,50].includes(v.pageSize)?v.pageSize:20;page=Number.isInteger(v.page)&&v.page>=0?v.page:0;}catch{filter='all';query='';group='all';sort='due';pageSize=20;page=0;}}
export function openComplianceTask(id){pendingTask=id;key='';}
// Opened from the reviewer overview: the version loads once the review room has refreshed.
let pendingVersion=null;export function openReviewVersion(id){pendingVersion=id;key='';}
export function openReviewGroup(group,filter='pending'){adminGroup=group;adminFilter=['pending','published','all'].includes(filter)?filter:'pending';adminQuery='';key='';}
let h,key='',loading=false,busy=false,error='',data=null,detail=null,editor=null,page=0,poll;
const labels={DRAFT:'Bản nháp',IN_REVIEW:'Chờ duyệt',PUBLISHED:'Đã duyệt',RETIRED:'Ngừng phát hành',TODO:'Chưa bắt đầu',DOING:'Đang thực hiện',DONE:'Hoàn tất',NOT_APPLICABLE:'Không áp dụng',APPLY:'Áp dụng',NOT_APPLY:'Không áp dụng',NEEDS_INFORMATION:'Cần xác minh',QUEUED:'Đang xếp hàng',COMPLETED:'Đã đánh giá',FAILED:'Đánh giá lỗi',AVAILABLE:'Đã lưu và kiểm tra',PENDING:'Chờ tải',UPLOADED:'Chờ kiểm tra',UPLOADING:'Đang tải',ABANDONED:'Đã hết hạn'};
const groups={tax:'Thuế',accounting:'Kế toán',labor:'Lao động',insurance:'Bảo hiểm',company:'Doanh nghiệp',commerce:'Thương mại',data:'Dữ liệu',fire:'PCCC',environment:'Môi trường',food:'Thực phẩm'};
const btn=(text,action,value='')=>`<button type="button" class="secondary-button" data-compliance="${action}" data-id="${esc(value)}" ${busy?'disabled':''}>${text}</button>`;
const field=(name,label,value='',type='text',required=true)=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${busy?'disabled':''} ${required?'required':''}></label>`;
const area=(name,label,value,required=true)=>`<label>${label}<textarea name="${name}" rows="4" ${busy?'disabled':''} ${required?'required':''}>${esc(value)}</textarea></label>`;
export function configureCompliance(hooks){h=hooks;}
export function invalidateCompliance(){key='';data=null;detail=null;editor=null;clearTimeout(poll);}
async function run(fn){if(busy)return;const formDrafts=captureFormDrafts();busy=true;error='';h.render();restoreFormDrafts(formDrafts);const action=beginAction();try{await fn();endAction(action);}catch(e){error=({SOURCE_ALREADY_EXISTS:'Văn bản này đã có trong thư viện. Hãy tìm và chọn căn cứ đã lưu.',SOURCE_NOT_ALLOWED:'Dùng đường dẫn bản gốc trên cổng thông tin chính thức.',SOURCE_PARSE_REQUIRED:'Văn bản chưa có nội dung đã tách. Cần kiểm tra dữ liệu nguồn.',INVALID_RELEASE:'Chọn ít nhất một checklist đã duyệt để phát hành.',RELEASE_REQUIRES_PUBLISHED_VERSIONS:'Mỗi checklist chỉ được chọn một phiên bản đã duyệt. Tải lại danh sách và chọn lại.',INVALID_REQUEST:'Kiểm tra lại các thông tin còn thiếu hoặc chưa hợp lệ trong checklist.',STEP_REASON_REQUIRED:'Ghi lý do cho từng tiêu chí không áp dụng.',NA_REASON_REQUIRED:'Ghi lý do không áp dụng toàn bộ công việc (ít nhất 3 ký tự).',REVIEW_INCOMPLETE:'Cần đánh giá đủ các điểm và xử lý các điểm còn thiếu trước khi kết thúc.',EVIDENCE_NOTE_REQUIRED:'Ghi vị trí lưu hoặc mã hồ sơ bằng chứng trước khi kết thúc.',PILOT_BASIS_CHANGED:'Bản nháp đã thay đổi. Tải lại để đối chiếu trước khi lưu.',NO_PUBLISHED_CATALOGUE:'Chưa có bộ nghĩa vụ được chuyên gia duyệt và phát hành. Bạn vẫn có thể hoàn thiện hồ sơ.',PROFILE_VERSION_CONFLICT:'Hồ sơ đã được cập nhật. Đóng và mở lại công việc để lấy thông tin mới.',UNEXPECTED_VERIFICATION_FACT:'Thông tin cần hỏi đã thay đổi. Đóng và mở lại công việc để tiếp tục.',REVISION_CONFLICT:'Dữ liệu đã thay đổi. Hãy tải lại trước khi lưu.',EVIDENCE_REQUIRED:'Cần tải bằng chứng đã được máy chủ kiểm tra.',STEPS_REQUIRED:'Hãy xác nhận đủ các bước trước khi hoàn thành.',NEEDS_INFORMATION:'Cần bổ sung hồ sơ hoặc mốc tính hạn trước khi hoàn thành.',OCR_REVIEW_REQUIRED:'Cần kiểm tra nội dung OCR và xác nhận từng căn cứ.',REJECTION_REASON_REQUIRED:'Ghi lý do trả lại ít nhất 3 ký tự.',INVALID_CITATION_CONFIRMATION:'Danh sách căn cứ xác nhận không hợp lệ. Tải lại và kiểm tra từng căn cứ.',ROLE_REJECTED:'Bạn chỉ có quyền xem.',REVIEWER_REQUIRED:'Chỉ chuyên gia được cấp quyền mới được duyệt.',ASSIGNEE_OUTSIDE_WORKSPACE:'Người phụ trách phải là thành viên của không gian này.'}[e.code])||e.message;}finally{busy=false;h.render();if(error){restoreFormDrafts(formDrafts);notify(error,'error');}if(!error&&detail?.revealWorkdate){detail.revealWorkdate=false;revealWorkDate();}}}
async function refresh(kind){
 if(!h.account())return;const c=h.company();
 if(kind==='admin'){
  const b=await h.api('/admin/obligations?summary=1');
  if(h.screen()!==kind)return;data={candidates:{items:[],total:0},versions:b.items,releases:[],imports:[],coverage:null};
 }else if(c){
  const [evaluations,dashboard]=await Promise.all([h.api(`/companies/${c.id}/evaluations`),h.api(`/companies/${c.id}/dashboard`)]);
  // The draft preview (pilot) mode is no longer offered: companies only see the published checklist.
  mode='official';
  const params=new URLSearchParams({page:String(page),summary:'1',filter,group,q:query,sort,pageSize:String(pageSize)});
  const [tasks,preview,coverage,attention]=await Promise.all([
   h.api(`/companies/${c.id}/tasks?${params}`),
   mode==='pilot'?h.api(`/companies/${c.id}/checklist-preview${assessmentDates.has(c.id)?'?asOfDate='+encodeURIComponent(assessmentDates.get(c.id)):''}`):Promise.resolve({items:[],questions:[],asOfDate:assessmentDates.get(c.id)||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date())}),
   data?.coverage?Promise.resolve(data.coverage):h.api(`/companies/${c.id}/checklist-coverage`),
   kind==='dashboard'?h.api(`/companies/${c.id}/tasks?view=today&summary=1&pageSize=20&page=${kind==='dashboard'?page:0}`):Promise.resolve(null)
  ]);
  if(h.screen()!==kind||h.company()?.id!==c.id)return;data={tasks,evaluations:evaluations.items,dashboard,preview,coverage,attention};
 }
 if(kind!=='admin'&&data?.evaluations.some(e=>e.status==='QUEUED')){clearTimeout(poll);poll=setTimeout(()=>{if(h.screen()===kind&&!detail&&!editor)void run(()=>refresh(kind));},1800);}
}
export function mountCompliance(){if(!h||busy)return;const kind=h.screen();if(!['admin','dashboard','checklist'].includes(kind)){key='';clearTimeout(poll);return;}const next=[kind,h.account()?.user.id,h.company()?.id].join(':');if(next!==key){key=next;page=0;mode='';if(kind==='checklist')loadView();else{filter='all';query='';group='all';}calendarOffset=0;data=null;detail=null;editor=null;loading=true;void run(async()=>{try{await refresh(kind);if(pendingTask&&kind==='checklist'){detail={type:'task',row:await h.api('/tasks/'+pendingTask)};pendingTask=null;}if(pendingVersion&&kind==='admin'){const id=pendingVersion;pendingVersion=null;await openVersion(id);}}finally{loading=false;}});}}
const cite=c=>`<details class="basis-item"><summary>${esc(c.snapshot?.document?.documentNumber||'Căn cứ')} · ${esc(c.provision?.heading||(c.quote||'').split('\n').find(x=>x.trim())?.slice(0,140)||'Điều khoản gốc')}</summary>${c.snapshot?.document?.title?`<strong>${esc(c.snapshot.document.title)}</strong>`:''}<a href="/workspace?view=laws&law=${esc(c.documentId)}&snapshotId=${esc(c.snapshotId)}&parseRunId=${esc(c.parseRunId)}&provision=${esc(c.provisionId)}" target="_blank" rel="noopener">Mở đúng điều khoản trong thư viện</a><p class="compliance-quote">${esc(c.quote)}</p></details>`;
export function renderCompliance(kind){
 if(!h?.account())return '';
 if(kind==='admin'&&!h.account().user.platformReviewer)return '<p>Bạn chưa được cấp quyền chuyên gia.</p>';
 if(kind!=='admin'&&!h.company())return '<p>Hãy chọn doanh nghiệp trước khi xem checklist.</p>';
 const top=`<section class="form-panel product-panel compliance-panel"><h1>${kind==='admin'?'Phòng duyệt nghĩa vụ':kind==='dashboard'?'Tổng quan doanh nghiệp':'Checklist doanh nghiệp'}</h1>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<div class="panel-actions">${btn('Tải lại','refresh')}${detail||editor||sourceImport?btn(kind==='admin'&&adminGroup?'Quay lại nhóm':'Quay lại danh sách','back'):''}</div>`;
 if(loading||!data||key!==[kind,h.account()?.user.id,h.company()?.id].join(':'))return top+'<p role="status">Đang tải dữ liệu từ máy chủ…</p></section>';
 if(sourceImport)return top+renderSourceImport()+'</section>';
 if(editor)return top+renderEditor()+'</section>';
 if(detail&&['task','pilot'].includes(detail.type))return renderWorkspace(kind);
 if(detail)return top+renderEvaluation(detail.row)+'</section>';
 if(kind==='admin')return top+renderAdmin()+'</section>';
 return renderWorkspace(kind);
}

function pagination(total,size=20,sizes=false){const pages=Math.max(1,Math.ceil(total/size)),from=total?page*size+1:0,to=Math.min(total,(page+1)*size);return `<div class="panel-actions list-pagination">${page>0?btn('Trang trước','previous'):''}<span>${from}–${to} / ${total} việc · Trang ${page+1}/${pages}</span>${(page+1)*size<total?btn('Trang sau','next'):''}${sizes?`<label class="page-size">Mỗi trang<select data-compliance-pagesize>${[10,20,50].map(n=>`<option value="${n}" ${n===size?'selected':''}>${n}</option>`).join('')}</select></label>`:''}</div>`;}
document.addEventListener('change',e=>{const s=e.target.closest('[data-compliance-pagesize]');if(!s||!h)return;pageSize=Number(s.value);page=0;saveView();void run(()=>refresh(h.screen()));});
function workspaceRows(){return mode==='pilot'?data.preview.items.map(x=>({...x,id:x.versionId,title:x.content.title,status:x.progress.status,applicability:x.decision,group:x.content.group,steps:x.progress.steps,pilot:true})):data.tasks.items.map(x=>({...x,group:x.basis?.contentJson.group||'company',content:x.basis?.contentJson,steps:x.stepsJson||[]}));}
function badge(t){const tone=t.applicability==='NEEDS_INFORMATION'?'amber':t.applicability==='NOT_APPLY'?'gray':['DONE','NOT_APPLICABLE'].includes(t.status)?'teal':t.status==='DOING'?'blue':'red';return `<span class="status-badge ${tone}"><span class="status-dot"></span>${esc(labels[t.applicability==='APPLY'?t.status:t.applicability])}</span>`;}
function liveCard(t){return `<article class="task-card"><div class="task-card-main"><div class="task-card-overline"><span>${esc(groups[t.group]||'Công việc')}</span><span class="law-backed">${t.pilot?'Căn cứ thật · bản nháp':'Căn cứ đã duyệt'}</span></div><h3>${esc(t.title)}</h3>${t.attentionDate?`<p class="field-hint">${esc(t.attentionLabel)}: ${esc(t.attentionDate)}</p>`:''}<p>${esc(t.applicability==='NEEDS_INFORMATION'?'Mở tóm tắt để xác minh phạm vi áp dụng':t.content?.action||t.explanation)}</p><div class="task-card-meta">${badge(t)}${t.pilot?'<span>Chạy thử · chưa duyệt</span>':''}${t.dueDate&&!t.attentionDate?`<span class="due-meta">${h.icon('calendar',14)} ${t.dueDateKind==='USER'?'Dự kiến':'Hạn'} ${esc(vnDate(t.dueDate))}</span>`:''}${t.content&&t.applicability!=='NEEDS_INFORMATION'&&!['COMPLETE','IGNORE'].includes(scopeVerification(t,Boolean(t.pilot))?.action)?`<span>${h.icon('check',14)} ${t.steps.length}/${t.content.steps.length} ${t.pilot?'bước thử':'bước'}</span>`:''}</div></div><button class="task-open" ${busy?'disabled':''} data-compliance="${t.pilot?'pilot':'task'}" data-id="${esc(t.id)}" aria-label="Xem chi tiết ${esc(t.title)}">${h.icon('arrow',19)}</button></article>`;}
function renderTodayQueue(rows){
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date()),end=new Date(today+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+7);const horizon=end.toISOString().slice(0,10);
 const buckets={overdue:[],soon:[],doing:[]};
 for(let t of rows){if(['DONE','NOT_APPLICABLE'].includes(t.status)||t.applicability==='NOT_APPLY')continue;const dates=[[t.legalDueDate||(t.dueDateKind!=='USER'?t.dueDate:null),'LEGAL'],[t.dueDateKind==='USER'?t.dueDate:null,'EXPECTED'],[reminderOf(t),'REMINDER']].filter(x=>x[0]).map(([d,k])=>[d.slice(0,10),k]).sort((a,b)=>a[0].localeCompare(b[0])),first=dates[0]?.[0];t={...t,attentionDate:vnDate(first),attentionLabel:DATE_LABELS[dates[0]?.[1]],sortDate:first||''};if(first&&first<today)buckets.overdue.push(t);else if(first&&first<=horizon)buckets.soon.push(t);else if(t.status==='DOING')buckets.doing.push(t);}
 const visible=Object.values(buckets).reduce((n,x)=>n+x.length,0);
 return `<div class="section-heading"><div><h2>Việc cần chú ý hôm nay</h2><p>Quá hạn, đến hạn trong 7 ngày tới và đang thực hiện.</p></div><button class="text-action" data-nav="checklist">Xem tất cả công việc</button></div>${[['overdue','Quá hạn'],['soon','Đến hạn hôm nay / trong 7 ngày tới'],['doing','Đang thực hiện']].map(([key,label])=>buckets[key].length?`<section class="today-work-group" data-today-group="${key}"><h3>${label} (${buckets[key].length})</h3><div class="task-list">${buckets[key].sort((a,b)=>a.sortDate.localeCompare(b.sortDate)).map(liveCard).join('')}</div></section>`:'').join('')}${!visible?'<div class="empty-state"><h3>Chưa có việc cần chú ý hôm nay</h3><p>Xem toàn bộ checklist và việc cần xác minh trong mục Công việc.</p><button class="secondary-button" data-nav="checklist">Mở Công việc</button></div>':''}${mode==='official'&&data.attention.total>20?pagination(data.attention.total,20):''}`;
}
function renderWorkspace(kind){
 const rows=workspaceRows(),pilot=mode==='pilot',counts=rows.reduce((a,t)=>{if(t.applicability==='NEEDS_INFORMATION')a.need++;else if(['DONE','NOT_APPLICABLE'].includes(t.status)||t.applicability==='NOT_APPLY')a.done++;else a.todo++;return a;},{todo:0,need:0,done:0}),total=pilot?rows.length:data.dashboard.total;
 if(!pilot){counts.done=data.dashboard.counts.filter(x=>['DONE','NOT_APPLICABLE'].includes(x.status)||x.applicability==='NOT_APPLY').reduce((n,x)=>n+x._count,0);counts.need=data.dashboard.counts.filter(x=>x.applicability==='NEEDS_INFORMATION'&&!['DONE','NOT_APPLICABLE'].includes(x.status)).reduce((n,x)=>n+x._count,0);counts.todo=Math.max(0,total-counts.done-counts.need);}
 const metrics=[['todo','Còn cần làm',counts.todo,'alert','red','Chưa bắt đầu hoặc đang thực hiện'],['need','Cần xác minh',counts.need,'help','amber','Bổ sung thông tin trước khi kết luận'],['done','Đã xử lý',counts.done,'check','teal',pilot?'Tiến độ thử và các mục không áp dụng':'Đã hoàn tất hoặc không áp dụng']];
 const stats=`<div class="metric-grid">${metrics.map(([key,label,count,glyph,tone,hint],index)=>{const pct=total?Math.round(count/total*100):0;return `<button class="metric-card metric-${tone}" ${kind==='dashboard'?'data-nav="checklist"':`data-compliance="filter" data-id="${key}"`}><span class="metric-top"><span>${label}</span><span class="summary-icon ${tone}">${h.icon(glyph,18)}</span></span><span class="metric-visual"><span class="metric-gauge" style="--gauge:${pct}%"><span><b>${String(count).padStart(2,'0')}<i>/${String(total).padStart(2,'0')}</i></b><small>${pct}%</small></span></span><span class="metric-mini-chart" aria-hidden="true">${[34+index*8,58-index*5,46+index*11,78-index*7].map(height=>`<i style="height:${height}%"></i>`).join('')}</span></span><span class="metric-hint">${hint}</span></button>`;}).join('')}</div>`;
 const toolbar='';
 const kpis=`<div class="today-kpis">${[['Quá hạn',data.dashboard.overdue||0,'red'],['Còn cần làm',counts.todo,'blue'],['Cần xác minh',counts.need,'amber'],['Đã xử lý',`${counts.done}/${total}`,'teal']].map(([l,n,tone])=>`<button type="button" class="today-kpi ${tone}" data-nav="checklist"><strong>${n}</strong><span>${l}</span></button>`).join('')}</div>`;
 // Ask first the profile questions that hold back the most items, instead of a 117-field form.
 const questions=pilot?data.preview.questions:data.dashboard.questions;
 const shown=questions?.slice(0,3)??[],waiting=pilot?shown.reduce((n,q)=>n+q.pending,0):(data.dashboard.questionTaskCount??shown.reduce((n,q)=>n+q.pending,0)),needTotal=pilot?rows.filter(t=>t.applicability==='NEEDS_INFORMATION').length:(data.dashboard.needTotal??counts.need);
 const unlock=shown.length?`<section class="verify-panel compact" aria-labelledby="verify-panel-title"><div class="verify-panel-head"><span class="verify-panel-icon" aria-hidden="true">${h.icon('help',18)}</span><div><h2 id="verify-panel-title">Cần bạn xác minh</h2><p>${shown.length} câu hỏi ưu tiên liên quan đến <strong>${waiting}</strong> trong <strong>${needTotal}</strong> việc cần xác minh. Mỗi câu trả lời dùng chung cho mọi việc liên quan.</p></div>${shown[0]?.taskId?`<button type="button" class="primary-button verify-start" data-compliance="task" data-id="${esc(shown[0].taskId)}" ${busy?'disabled':''}>Bắt đầu trả lời</button>`:''}</div><ul class="verify-panel-list">${shown.map(q=>`<li class="verify-item">${q.taskId?`<button type="button" data-compliance="task" data-id="${esc(q.taskId)}" ${busy?'disabled':''}>`:'<span>'}<strong>${esc(factLabel(q.fact))}</strong><small>${q.pending} việc</small>${q.taskId?'</button>':'</span>'}</li>`).join('')}</ul></section>`:'';
 const notice=pilot?`<div class="disclaimer-banner">${h.icon('help',18)}<span>${esc(data.preview.notice)}</span></div>`:'';
 const matched=!pilot?rows:rows.filter(t=>(filter==='all'||filter==='need'&&t.applicability==='NEEDS_INFORMATION'||filter==='done'&&(['DONE','NOT_APPLICABLE'].includes(t.status)||t.applicability==='NOT_APPLY')||filter==='todo'&&!['DONE','NOT_APPLICABLE'].includes(t.status)&&t.applicability==='APPLY')&&(group==='all'||t.group===group)&&(!query||t.title.toLocaleLowerCase('vi').includes(query)));
 const controls=`<div class="tab-bar" role="tablist" aria-label="Lọc công việc">${[['all','Tất cả',total],['todo','Còn cần làm',counts.todo],['need','Cần xác minh',counts.need],['done','Đã xử lý',counts.done]].map(([k,l,n])=>`<button ${busy?'disabled':''} role="tab" aria-selected="${filter===k}" class="${filter===k?'active':''}" data-compliance="filter" data-id="${k}">${l}<span>${n}</span></button>`).join('')}</div><form id="compliance-filter" class="list-controls"><label class="search-control">${h.icon('search',17)}<input name="query" value="${esc(query)}" placeholder="Tìm công việc…" aria-label="Tìm công việc"></label><label>Nhóm<select name="group"><option value="all">Tất cả</option>${Object.entries(groups).map(([k,v])=>`<option value="${k}" ${group===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Sắp xếp<select name="sort"><option value="due" ${sort==='due'?'selected':''}>Hạn gần nhất</option><option value="title" ${sort==='title'?'selected':''}>Tên A–Z</option><option value="recent" ${sort==='recent'?'selected':''}>Mới cập nhật</option></select></label><button class="secondary-button">Áp dụng</button>${btn('Tải lại','refresh')}</form>`;
 const list=`<div class="task-list checklist-list">${matched.length?matched.map(liveCard).join(''):`<div class="empty-state">${h.icon('search',28)}<h3>${pilot?'Không có công việc khớp bộ lọc':'Không có công việc khớp bộ lọc'}</h3><p>${pilot?'Đổi bộ lọc hoặc bổ sung hồ sơ doanh nghiệp.':'Đổi trạng thái, nhóm hoặc từ khóa để xem công việc khác.'}</p></div>`}</div>`;
 const progress=total?Math.round(counts.done/total*100):0;
 const rail=`<aside class="right-rail"><section class="progress-card"><div class="section-heading"><h3>Tiến độ ${pilot?'chạy thử':'công việc'}</h3>${h.icon('list',19)}</div><div class="progress-visual"><div class="progress-value"><strong>${counts.done}<small> / ${total}</small></strong><span>mục đã xử lý</span></div><div class="progress-donut" style="--progress:${progress}%" role="progressbar" aria-label="Tiến độ xử lý" aria-valuenow="${progress}" aria-valuemin="0" aria-valuemax="100"><span><strong>${progress}%</strong><small>${counts.done}/${total}</small></span></div></div><p>Đây là tiến độ xử lý, không phải điểm tuân thủ.</p></section><section class="event-panel"><div class="section-heading"><div><span class="rail-kicker">DOANH NGHIỆP THAY ĐỔI?</span><h3>Cập nhật hồ sơ</h3></div>${h.icon('rotate',19)}</div><p>Hồ sơ phiên bản ${h.company().version}. Quy mô lao động đã xác nhận được dùng để đánh giá. Cập nhật hồ sơ khi hoạt động thực tế thay đổi.</p><div class="event-actions"><button data-nav="profile">${h.icon('building',17)} Chỉnh hồ sơ doanh nghiệp</button><button data-nav="laws">${h.icon('file',17)} Tra cứu văn bản gốc</button></div></section><div class="session-note saved">${h.icon('check',17)}<span>Tiến độ được lưu theo tài khoản trên máy chủ.</span></div></aside>`;
 const evaluateForm=h.canEdit()?`<form id="compliance-evaluate" class="live-evaluate">${field('asOfDate','Ngày đánh giá',data.preview.asOfDate,'date')}<button class="primary-button" ${busy||!pilot&&!data.dashboard.publishedReleases?'disabled':''}>${pilot?'Đánh giá thử hồ sơ':'Sinh checklist chính thức'}</button></form>`:'';
 return h.pageTitle(kind==='dashboard'?'ƯU TIÊN HÔM NAY':'CÔNG VIỆC CỦA DOANH NGHIỆP',kind==='dashboard'?'Việc doanh nghiệp cần chú ý':'Công việc tuân thủ',h.company().profileJson.name,kind==='dashboard'?`<span class="today-label">${h.icon('calendar',17)}${esc(new Date().toLocaleDateString('vi-VN',{day:'2-digit',month:'long',year:'numeric'}))}</span>`:`<button class="secondary-button" data-nav="profile">${h.icon('building',17)} Điều chỉnh hồ sơ</button>`)+(error?`<p class="form-error" role="alert">${esc(error)}</p>`:'')+toolbar+notice+unlock+(!data.dashboard.publishedReleases?'<p class="info-callout">Chưa có bộ nghĩa vụ được chuyên gia phát hành. Bạn có thể dùng các checklist chạy thử đã được gắn nhãn bản nháp.</p>':'')+(kind==='dashboard'?kpis+renderLiveCalendar(rows):stats)+`<div class="dashboard-lower"><section><div class="section-heading"><div><h2>${kind==='dashboard'?'Ưu tiên xử lý':pilot?'Checklist chạy thử':'Tất cả công việc'}</h2><p>${pilot?`${data.preview.blockedCount} mục khác đang chờ bổ sung điều kiện và căn cứ trước khi đưa vào thử.`:'Căn cứ và tiến độ được giữ để đối chiếu.'}</p></div></div>${kind==='dashboard'?renderTodayQueue(pilot?rows:data.attention.items.map(x=>({...x,group:x.basis?.contentJson.group||'company',content:x.basis?.contentJson,steps:x.stepsJson||[]}))):controls+list+(!pilot?pagination(data.tasks.total,pageSize,true):'')}</section>${rail}</div><details class="reviewer-aux"><summary>Đánh giá theo ngày và phạm vi dữ liệu</summary>${evaluateForm}${renderCoverage()}</details>`;
}
function renderLiveCalendar(rows){const cursor=new Date();cursor.setMonth(cursor.getMonth()+calendarOffset,1);const year=cursor.getFullYear(),month=cursor.getMonth(),offset=(new Date(year,month,1).getDay()+6)%7,events=rows.filter(t=>t.applicability==='APPLY'&&!['DONE','NOT_APPLICABLE'].includes(t.status)).flatMap(t=>[...(t.dueDate?[t]:[]),...(!t.pilot&&t.dueDateKind==='USER'&&t.legalDueDate&&t.legalDueDate.slice(0,10)!==t.dueDate?.slice(0,10)?[{...t,dueDate:t.legalDueDate,dueDateKind:'LEGAL'}]:[]),...(reminderOf(t)?[{...t,dueDate:reminderOf(t),dueDateKind:'REMINDER',userReminder:true}]:[])]);const date=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,monthCount=events.filter(t=>t.dueDate.slice(0,7)===date(cursor).slice(0,7)).length,open=calendarOpen??monthCount>0;
 // A month without milestones only needs one line; the grid opens on demand.
 if(!open)return `<section class="compliance-calendar collapsed"><div class="calendar-collapsed">${h.icon('calendar',18)}<span><strong>${esc(cursor.toLocaleDateString('vi-VN',{month:'long',year:'numeric'}))}</strong> · ${monthCount?monthCount+' mốc trong tháng':'Không có mốc trong tháng'}</span><div class="calendar-controls"><button class="calendar-nav prev" data-compliance="calendar" data-id="-1" aria-label="Tháng trước">${h.icon('chevron',17)}</button><button class="calendar-nav" data-compliance="calendar" data-id="1" aria-label="Tháng sau">${h.icon('chevron',17)}</button><button class="text-action" data-compliance="calendar-toggle">Mở lịch</button></div></div></section>`;
 return `<section class="compliance-calendar"><header class="calendar-header"><div><span class="rail-kicker">LỊCH TUÂN THỦ</span><h2>Mốc pháp lý và công việc</h2></div><div class="calendar-controls"><button class="calendar-nav prev" data-compliance="calendar" data-id="-1" aria-label="Tháng trước">${h.icon('chevron',17)}</button><button class="calendar-today" data-compliance="calendar-reset">Tháng hiện tại</button><button class="text-action" data-compliance="calendar-toggle">Thu gọn</button><button class="calendar-nav" data-compliance="calendar" data-id="1" aria-label="Tháng sau">${h.icon('chevron',17)}</button></div></header><div class="calendar-summary"><strong>${esc(cursor.toLocaleDateString('vi-VN',{month:'long',year:'numeric'}))}</strong><span>${events.filter(t=>t.dueDate.slice(0,7)===date(cursor).slice(0,7)).length} mốc trong tháng</span><div class="calendar-legend"><span><i class="deadline"></i>Hạn pháp lý</span><span><i class="expected"></i>Ngày dự kiến hoàn thành</span><span><i class="reminder"></i>Ngày nhắc</span></div></div><div class="calendar-layout"><div class="calendar-grid-wrap"><div class="calendar-grid"><div class="calendar-weekdays">${['Thứ 2','Thứ 3','Thứ 4','Thứ 5','Thứ 6','Thứ 7','Chủ nhật'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-days">${Array.from({length:42},(_,i)=>{const d=new Date(year,month,1-offset+i),key=date(d);return `<div class="calendar-day ${d.getMonth()===month?'':'outside'} ${key===date(new Date())?'today':''}"><div class="calendar-date"><span>${d.getDate()}</span></div><div class="calendar-day-events">${events.filter(t=>t.dueDate.slice(0,10)===key).map(t=>`<button class="calendar-event tone-${t.userReminder?'reminder':t.dueDateKind==='USER'?'expected':'deadline'} related" data-compliance="${t.pilot?'pilot':'task'}" data-id="${esc(t.id)}"><small>${t.userReminder?'Ngày nhắc':t.dueDateKind==='USER'?'Dự kiến hoàn thành':'Hạn pháp lý'}</small><span>${esc(t.title)}</span></button>`).join('')}</div></div>`;}).join('')}</div></div></div>${renderUpcoming(events)}</div></section>`;}
function scopeVerification(t,pilot){return (pilot?t.progress.review:t.reviewJson)?.scopeVerification;}
function summaryOnly(t,pilot){const record=scopeVerification(t,pilot);return record?record.action!=='PROCESS':(pilot?t.decision:t.applicability)==='NEEDS_INFORMATION';}
function periodLabel(key){if(key==='once')return 'Thiết lập ban đầu';if(/^\d{4}$/.test(key))return 'Năm '+key;const [field,...parts]=key.split(':');return factLabel(field)+(parts.length?': '+parts.join(':'):'');}
function detailReview(t,pilot){if(!detail.draftReview)detail.draftReview=reviewState(pilot?t.progress.review:t.reviewJson,pilot?t.progress.steps:t.stepsJson);return detail.draftReview;}
function completionState(t,pilot,r){const c=pilot?t.content:t.basis.contentJson,issues=r.steps.filter(x=>x.result==='issue').length,missing=Math.max(0,c.steps.length-r.steps.length),reasonMissing=r.steps.some(x=>x.result==='na'&&!x.note.trim()),fileMissing=!pilot&&c.evidenceRequired&&!t.evidence.some(x=>x.state==='AVAILABLE'&&x.basisVersionId===t.basisVersionId),factsMissing=!pilot&&t.missingFacts.length>0,ready=!issues&&!missing&&!reasonMissing&&Boolean(r.evidenceNote.trim())&&!fileMissing&&!factsMissing&&(pilot?t.decision:t.applicability)==='APPLY';const assessedIdx=new Set(r.steps.map(x=>x.index)),firstIssue=r.steps.find(x=>x.result==='issue'),firstMissing=c.steps.findIndex((_,i)=>!assessedIdx.has(i)),firstReason=r.steps.find(x=>x.result==='na'&&!x.note.trim());
 const [note,target,action]=issues?[`${issues} điểm đang “Cần xử lý” — xử lý xong mới kết thúc được.`,`[data-review-index="${firstIssue.index}"]`,'Xem điểm cần xử lý']:missing?[`Còn ${missing} điểm chưa kiểm tra.`,`[data-review-index="${firstMissing}"]`,'Kiểm tra điểm tiếp theo']:reasonMissing?['Đã kiểm tra đủ các điểm — còn thiếu lý do cho điểm “Không áp dụng”.',`[name="step-note-${firstReason.index}"]`,'Ghi lý do']:!r.evidenceNote.trim()?['Đã kiểm tra đủ các điểm — còn thiếu mô tả bằng chứng.','[name="evidenceNote"]','Điền mô tả bằng chứng']:fileMissing?['Đã kiểm tra đủ các điểm — còn thiếu tệp bằng chứng.','#compliance-upload [name="file"]','Tải tệp bằng chứng']:factsMissing?['Còn thông tin hoặc mốc tính hạn cần xác nhận trong hồ sơ.','#compliance-answer','Xác nhận thông tin']:ready?['Đủ điều kiện kết thúc. Đây không phải xác nhận tuân thủ pháp luật.','','']:['Chưa xác định công việc áp dụng.','',''];return {ready,note,target,action};}
function workDate(t,pilot){return pilot?detailReview(t,true).reminderDate:detail.draftDueDate??(t.dueDateKind==='USER'?t.dueDate?.slice(0,10):'');}
function revealWorkDate(){const input=document.querySelector('#product-work-date'),sheet=document.querySelector('.sheet-content');if(!input||!sheet)return;const prompt=input.closest('.deadline-prompt')||input,box=prompt.getBoundingClientRect(),visible=sheet.getBoundingClientRect();if(box.bottom>visible.bottom||box.top<visible.top)prompt.scrollIntoView({block:'nearest',behavior:'instant'});input.focus({preventScroll:true});}
function workDatePrompt(t,pilot){const status=detail.draftStatus||(pilot?t.progress.status:t.status),date=workDate(t,pilot);if(status!=='DOING'||date&&!detail.editingDeadline)return '';const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date());return `<div class="deadline-prompt"><strong>${date?'Đổi ngày dự kiến hoàn thành':'Chọn ngày dự kiến hoàn thành'}</strong><label for="product-work-date">Ngày dự kiến hoàn thành<input id="product-work-date" name="workDeadline" form="workdate-selection" type="date" min="${today}" value="${esc(detail.draftWorkDeadline??date??'')}" ${!h.canEdit()?'disabled':''}></label><button type="button" class="primary-button" data-save-workdate ${busy||!h.canEdit()?'disabled':''}>${date?'Cập nhật':'Lưu ngày'}</button><p class="detail-hint">Mốc nội bộ do bạn đặt, không thay đổi hạn pháp lý.</p></div>`;}
function reviewControls(t,pilot){const r=detailReview(t,pilot),status=detail.draftStatus||(pilot?t.progress.status:t.status);return `<input type="hidden" name="status" value="${esc(status)}"><div class="answer-grid"><button type="button" class="answer-option ${status==='DOING'?'selected':''}" data-review-status="DOING">Đang thực hiện</button><button type="button" class="answer-option ${status==='NOT_APPLICABLE'?'selected':''}" data-review-status="NOT_APPLICABLE">Không áp dụng toàn bộ</button></div>${workDatePrompt(t,pilot)}<input type="hidden" name="notApplicableReason" value="${esc(r.notApplicableReason)}">`;}
function renderPilot(t){const c=t.content;if(summaryOnly(t,true))return renderVerificationSummary(c,t.citations,{missingFacts:t.missingFacts.map(factLabel),explanation:t.explanation,esc,icon:h.icon,cite});const r=detailReview(t,true);return `<div class="info-callout">Chạy thử từ luật thật · Chưa được chuyên gia duyệt. Kết quả được lưu riêng theo doanh nghiệp.</div><p>${esc(labels[t.decision])} · ${esc(t.explanation)}</p>${t.missingFacts.length?`<div class="verification-brief"><p>Cần bổ sung: ${t.missingFacts.map(x=>esc(factLabel(x))).join(', ')}</p><button class="secondary-button" data-nav="profile">Cập nhật hồ sơ doanh nghiệp</button></div>`:''}${t.progress.stale?'<div class="info-callout">Căn cứ hoặc kỳ kiểm tra đã đổi. Kiểm tra lại từng điểm trước khi lưu kết quả mới.</div>':''}<p>${t.dueDate?`Ngày tính theo quy tắc nháp: ${esc(t.dueDate)} · Kỳ: ${esc(periodLabel(t.periodKey))}`:c.deadline.kind==='REVIEW_PERIOD'?'Kỳ kiểm tra: '+esc(periodLabel(t.periodKey))+'. Không tự đặt ngày đến hạn.':'Mục kiểm tra quy trình: theo dõi riêng hạn của từng hồ sơ, cơ sở hoặc sự kiện; ứng dụng chưa tự tính các hạn đó.'}</p><p>${esc(t.reviewNotes.deadlineExplanation||'')}</p><form id="compliance-pilot" class="product-form"><fieldset ${!h.canEdit()?'disabled':''}>${renderGuide(c,t.citations,{review:r,openGroups:detail.openGroups,controls:reviewControls(t,true),ownerControls:`${field('owner','Người phụ trách bạn phân công',r.owner,'text',false)}${field('reminderDate','Nhắc trong LIMI vào ngày (mốc nội bộ)',r.reminderDate||'','date',false)}<p class="detail-hint">Mốc nội bộ được lưu và hiển thị trong LIMI, không tự gửi email hoặc thay đổi hạn pháp lý.</p>`,readOnly:!h.canEdit()||t.decision!=='APPLY',esc,icon:h.icon,cite})}<label class="review-note">Ghi chú rà soát<textarea name="note" rows="3" maxlength="2000">${esc(detail.draftNote??t.progress.note)}</textarea></label><button class="primary-button" ${busy?'disabled':''}>Lưu kết quả rà soát</button></fieldset></form><details><summary>Những điểm chuyên gia cần kiểm tra</summary>${(t.reviewNotes.openQuestions||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</details>`;}
export function renderComplianceOverlay(){if(!detail||!['dashboard','checklist'].includes(h.screen())||!['task','pilot'].includes(detail.type))return '';if(detail.pendingDecision)return renderDecisionDialog();const t=detail.row,pilot=detail.type==='pilot',c=pilot?t.content:t.basis.contentJson,summary=summaryOnly(t,pilot),r=detailReview(t,pilot),completion=completionState(t,pilot,r),complete=completion.ready;return `<div class="overlay-backdrop"><aside class="detail-sheet" role="dialog" aria-modal="true" aria-label="Chi tiết công việc"><div class="sheet-top"><span class="status-badge">${esc(summary?(['DONE','NOT_APPLICABLE'].includes(pilot?t.progress.status:t.status)?labels[pilot?t.progress.status:t.status]:'Cần xác minh'):labels[detail.draftStatus||(pilot?t.progress.status:t.status)])}</span>${!summary&&(detail.draftStatus||(pilot?t.progress.status:t.status))==='DOING'&&workDate(t,pilot)?`<button type="button" class="deadline-chip" data-edit-workdate>${h.icon('calendar',15)} Dự kiến hoàn thành · ${esc(vnDate(workDate(t,pilot)))}</button>`:''}<button type="button" class="close-button" data-compliance="back" aria-label="Đóng">${h.icon('close',20)}</button></div><div class="sheet-content"><span class="rail-kicker">${esc(groups[c.group])}</span><h2>${esc(c.title)}</h2>${!pilot?'<div class="task-feedback-link"><button type="button" class="text-action" data-compliance="report">Báo vấn đề về công việc</button></div>':''}${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}${pilot?renderPilot(t):renderTask(t)}${summary?'<button type="button" class="text-action" data-nav="profile">Cập nhật hồ sơ nếu cần</button>':''}</div><div class="sheet-footer detail-footer">${summary?`<div class="completion-note">Trả lời câu hỏi để tự cập nhật các việc liên quan. Hoặc tự xác minh mục này bằng các lựa chọn bên dưới.</div><button type="button" class="primary-button" data-scope-action="PROCESS" ${busy||!h.canEdit()?'disabled':''}>Cần xử lý ${h.icon('arrow',17)}</button><button type="button" class="secondary-button verify-complete" data-scope-action="COMPLETE" ${busy||!h.canEdit()?'disabled':''}>${h.icon('check',17)} Đã hoàn thành</button><button type="button" class="ghost-danger" data-scope-action="IGNORE" ${busy||!h.canEdit()?'disabled':''}>Bỏ qua</button>`:`<div class="completion-note ${complete?'ready':'blocked'}"><span data-completion-note>${esc(completion.note)}</span><button type="button" class="text-action completion-jump" data-completion-jump="${esc(completion.target)}" ${completion.target?'':'hidden'}>${esc(completion.action)} ${h.icon('arrow',14)}</button></div><button type="button" class="primary-button" data-review-finish ${busy||!h.canEdit()||!complete?'disabled':''}>Kết thúc rà soát</button><button type="button" class="ghost-danger" data-review-status="NOT_APPLICABLE" ${busy||!h.canEdit()?'disabled':''}>Không áp dụng toàn bộ</button>`}</div></aside></div>`;}
function renderDecisionDialog(){const skip=detail.pendingDecision==='IGNORE';return `<div class="overlay-backdrop centered"><div class="reason-dialog" role="dialog" aria-modal="true" aria-labelledby="scope-reason-title"><button type="button" class="close-button" data-scope-cancel aria-label="Đóng">${h.icon('close',20)}</button><div class="dialog-icon">${h.icon('help',22)}</div><h2 id="scope-reason-title">${skip?'Vì sao bỏ qua mục này?':'Vì sao công việc này không áp dụng?'}</h2><form id="compliance-decision"><label for="scope-reason">${skip?'Lý do bỏ qua':'Lý do ngắn'}</label><textarea id="scope-reason" name="reason" rows="4" required minlength="3" maxlength="2000"></textarea>${error?`<p class="form-error" role="alert">${esc(error)}</p>`:''}<div class="dialog-actions"><button type="button" class="secondary-button" data-scope-cancel>Hủy</button><button class="primary-button" ${busy?'disabled':''}>${skip?'Bỏ qua mục này':'Lưu trạng thái'}</button></div></form></div></div>`;}
document.addEventListener('click',e=>{if(e.target.closest('[data-answer-unknown]'))notify('Giữ công việc ở Cần xác minh. Bạn có thể quay lại khi đã rõ thông tin.','info');});
document.addEventListener('submit',e=>{
 if(e.target.id!=='compliance-answer')return;e.preventDefault();if(busy||!h.canEdit()||!detail)return;
 const form=e.target,d=detail,t=d.row,q=t.verification.questions[0],fd=new FormData(form);
 const value=e.submitter?.name==='answer'?e.submitter.value:fd.get('answer');if(value===null||value==='')return;
 const workForm=document.querySelector('#compliance-task');if(workForm)captureReview(workForm);
 void run(async()=>{
  const result=await h.api('/tasks/'+t.id+'/answers','POST',{expectedRevision:t.revision,expectedProfileVersion:t.verification.profileVersion,answers:{[q.fact]:q.kind==='number'?Number(value):value}});
  if(detail!==d)return;await h.refreshProfile?.();if(detail!==d)return;
  const next=await h.api('/tasks/'+result.task.id);if(detail!==d)return;
  detail.row=next;
  if(next.applicability==='NOT_APPLY'){filter='done';page=0;detail=null;notify('Đã lưu câu trả lời. Công việc không thuộc phạm vi theo hồ sơ hiện tại.');}
  else if(next.applicability==='APPLY'){filter='todo';page=0;notify('Đã lưu câu trả lời và mở checklist cần xử lý. Các việc liên quan cũng được cập nhật.');}
  else notify(result.evaluationPending?'Đã lưu câu trả lời, đang chờ đánh giá lại.':'Đã lưu câu trả lời. Chỉ còn xác minh thông tin tiếp theo.');
  await refresh(h.screen());
 });
});
async function verifyScope(action,reason=''){const d=detail,t=d.row,pilot=d.type==='pilot';await run(async()=>{await h.api(pilot?`/companies/${h.company().id}/pilot-checklist/${t.versionId}/verify-scope`:`/tasks/${t.id}/verify-scope`,'POST',{action,reason,expectedRevision:pilot?t.progress.revision:t.revision,...(pilot?{basisHash:t.basisHash,asOfDate:data.preview.asOfDate}:{})});if(detail!==d)return;filter=action==='PROCESS'?'todo':'done';page=0;await refresh(h.screen());if(detail!==d)return;detail=null;});}
document.addEventListener('click',e=>{const b=e.target.closest('[data-scope-action],[data-scope-cancel]');if(!b||!detail)return;if(b.hasAttribute('data-scope-cancel')){detail.pendingDecision=null;h.render();return;}if(!h.canEdit()||busy)return;if(b.dataset.scopeAction==='IGNORE'){detail.pendingDecision='IGNORE';h.render();document.querySelector('#scope-reason')?.focus();}else void verifyScope(b.dataset.scopeAction);});
document.addEventListener('submit',e=>{if(e.target.id!=='compliance-decision')return;e.preventDefault();const reason=String(new FormData(e.target).get('reason')||'').trim();if(reason.length<3||busy)return;if(detail.pendingDecision==='IGNORE'){void verifyScope('IGNORE',reason);return;}const d=detail,t=d.row,pilot=d.type==='pilot',r=detailReview(t,pilot);r.notApplicableReason=reason;void run(async()=>{await h.api(pilot?`/companies/${h.company().id}/pilot-checklist/${t.versionId}`:`/tasks/${t.id}`,'PATCH',{expectedRevision:pilot?t.progress.revision:t.revision,status:'NOT_APPLICABLE',review:r,steps:r.steps.filter(x=>x.result!=='issue').map(x=>x.index),note:reason,...(pilot?{basisHash:t.basisHash,asOfDate:data.preview.asOfDate}:{})});filter='done';page=0;await refresh(h.screen());detail=null;});});
function captureReview(form){if(!form||!detail)return;detail.openGroups=[...form.querySelectorAll('[data-review-group]')].filter(x=>x.open).map(x=>Number(x.dataset.reviewGroup));const fd=new FormData(form);const workInput=document.querySelector('#product-work-date');if(workInput)detail.draftWorkDeadline=workInput.value;const r=detailReview(detail.row,detail.type==='pilot');for(const step of r.steps)step.note=String(fd.get('step-note-'+step.index)||'');r.evidenceNote=String(fd.get('evidenceNote')||'');r.notApplicableReason=String(fd.get('notApplicableReason')||'');r.owner=String(fd.get('owner')||'');r.reminderDate=String(fd.get('reminderDate')||'')||null;detail.draftStatus=String(fd.get('status')||'TODO');detail.draftNote=String(fd.get('note')||'');detail.draftAssignee=String(fd.get('assigneeId')||'');detail.draftDueDate=String(fd.get('dueDate')||'');const finish=document.querySelector('[data-review-finish]'),content=detail.type==='pilot'?detail.row.content:detail.row.basis.contentJson;const reasonBox=document.querySelector('[data-whole-reason]');if(reasonBox)reasonBox.style.display=detail.draftStatus==='NOT_APPLICABLE'||r.notApplicableReason?'':'none';const completion=completionState(detail.row,detail.type==='pilot',r);if(finish)finish.disabled=busy||!h.canEdit()||!completion.ready;const note=document.querySelector('[data-completion-note]');if(note){note.textContent=completion.note;note.parentElement.className='completion-note '+(completion.ready?'ready':'blocked');}const jump=document.querySelector('[data-completion-jump]');if(jump){jump.dataset.completionJump=completion.target;jump.hidden=!completion.target;jump.firstChild.textContent=completion.action+' ';}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-completion-jump]');if(!b)return;const el=b.dataset.completionJump&&document.querySelector('.sheet-content')?.querySelector(b.dataset.completionJump);if(!el)return;for(let p=el;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;el.scrollIntoView({block:'center',behavior:'smooth'});(el.matches('input,textarea,select')?el:el.querySelector('button,textarea,input'))?.focus({preventScroll:true});el.closest('.review-step')?.classList.add('flash');setTimeout(()=>el.closest('.review-step')?.classList.remove('flash'),1600);});
document.addEventListener('click',e=>{const b=e.target.closest('[data-edit-workdate],[data-save-workdate]');if(!b||!detail||!h.canEdit()||busy)return;const form=document.querySelector('#compliance-pilot,#compliance-task');if(!form)return;captureReview(form);if(b.hasAttribute('data-edit-workdate')){detail.editingDeadline=true;h.render();revealWorkDate();return;}const input=document.querySelector('#product-work-date');if(!input)return;if(!input.value){input.setCustomValidity('Chọn ngày dự kiến hoàn thành.');input.reportValidity();input.setCustomValidity('');return;}if(!input.reportValidity())return;const date=input.value;form.elements[detail.type==='pilot'?'reminderDate':'dueDate'].value=date;detail.editingDeadline=false;delete detail.draftWorkDeadline;form.requestSubmit();});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='product-work-date'){e.preventDefault();document.querySelector('[data-save-workdate]')?.click();}});
document.addEventListener('input',e=>{const form=e.target.closest('#compliance-pilot,#compliance-task');if(form)captureReview(form);});
document.addEventListener('change',e=>{const form=e.target.closest('#compliance-pilot,#compliance-task');if(form)captureReview(form);});
document.addEventListener('click',e=>{if(e.target.closest('[data-nav]')&&['task','pilot'].includes(detail?.type))detail=null;const b=e.target.closest('[data-review-result],[data-review-status],[data-review-finish],[data-guide-edit]');if(!b||!h)return;
 if(b.dataset.guideEdit!==undefined){if(editor?.row.status==='DRAFT'){editor.tab='edit';h.render();if(editor.savedDrafts)restoreFormDrafts(editor.savedDrafts);}const form=document.querySelector('#compliance-draft'),section=form?.querySelector('#guide-edit-'+b.dataset.guideEdit);if(section){let parent=section;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}section.scrollIntoView({block:'center'});section.querySelector('textarea')?.focus({preventScroll:true});}return;}
 const form=document.querySelector('#compliance-pilot,#compliance-task');if(!form||!h.canEdit())return;captureReview(form);
 if(b.hasAttribute('data-review-finish')){form.elements.status.value='DONE';form.requestSubmit();return;}
 if(b.dataset.reviewStatus==='NOT_APPLICABLE'){detail.pendingDecision='NOT_APPLICABLE';h.render();document.querySelector('#scope-reason')?.focus();return;}
 if(b.dataset.reviewStatus){detail.revealWorkdate=b.dataset.reviewStatus==='DOING'&&!workDate(detail.row,detail.type==='pilot');form.elements.notApplicableReason.value='';form.elements.status.value=b.dataset.reviewStatus;form.requestSubmit();return;}
 const r=detail.draftReview,index=Number(b.dataset.reviewStep),old=r.steps.find(x=>x.index===index);r.steps=r.steps.filter(x=>x.index!==index);r.steps.push({index,result:b.dataset.reviewResult,note:old?.note||''});const content=document.querySelector('.sheet-content'),top=content?.scrollTop||0;h.render();const next=document.querySelector('.sheet-content');if(next)next.scrollTop=top;document.querySelector('[name=step-note-'+index+']')?.focus({preventScroll:true});
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&detail&&['task','pilot'].includes(detail.type)){detail=null;h.render();window.scrollTo({top:listScroll});}});
function renderReviewNotes(id){const notes=data.imports?.find(x=>x.versionId===id)?.notesJson;if(!notes)return '';return `<details><summary>Lưu ý cần xác minh từ dữ liệu nguồn</summary>${['reasonForSelection','ruleExplanation','deadlineExplanation'].map(k=>`<p>${esc(notes[k])}</p>`).join('')}<h3>Cần chuyên gia xác nhận</h3><ul>${(notes.openQuestions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`;}
function renderUpcoming(events){const today=data.preview.asOfDate,upcoming=events.filter(t=>t.dueDate.slice(0,10)>=today).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,8);return `<aside class="upcoming-events"><div class="upcoming-heading"><div><span class="rail-kicker">SẮP TỚI</span><h3>Các mốc gần nhất</h3></div><span>${upcoming.length}</span></div>${upcoming.map(t=>{const bits=t.dueDate.slice(0,10).split('-');return `<div class="upcoming-row"><time datetime="${esc(t.dueDate.slice(0,10))}"><strong>${bits[2]}</strong><span>Thg ${bits[1]}</span></time><button class="calendar-event compact tone-${t.userReminder?'reminder':t.dueDateKind==='USER'?'expected':'deadline'} related" data-compliance="${t.pilot?'pilot':'task'}" data-id="${esc(t.id)}"><small>${t.userReminder?'Ngày nhắc':t.dueDateKind==='USER'?'Dự kiến hoàn thành':'Hạn pháp lý'}</small><span>${esc(t.title)}</span></button></div>`;}).join('')||'<p class="calendar-empty">Chưa có hạn sắp tới trong bộ đang chọn. Mục không quy định hạn không được gán ngày giả.</p>'}</aside>`;}
function renderImportQueue(){const blocked=(data.imports||[]).filter(x=>x.blockedJson);return `<div class="info-callout">Đã nhập ${(data.imports||[]).filter(x=>x.versionId).length} bản nháp từ dữ liệu thật. ${blocked.length} mục từ lần nhập đầu còn cần đối chiếu phạm vi và hạn; một số nhánh đã có checklist bổ sung. Không tự động duyệt hoặc phát hành.</div><details><summary>Các mục cần hoàn thiện (${blocked.length})</summary>${blocked.map(x=>{const b=x.blockedJson;return `<section class="compliance-candidate"><h3>${esc(b.title)}</h3><p>${esc(b.reason)}</p><p>Thông tin cần thêm: ${(b.requiredFacts||[]).map(esc).join(', ')||'Đối chiếu ghi chú'}</p><p>Cách tính hạn cần hỗ trợ: ${esc(b.requiredDeadlineCapability||'Xem điều khoản')}</p>${(b.sourceReferences||[]).map(ref=>`<p>${esc(ref.documentNumber)} · ${esc(ref.heading)}</p>${ref.documentId?cite(ref):''}`).join('')}</section>`;}).join('')}</details>`;}
function renderAdmin(){const groupsData=reviewGroups(data.versions,groups),selected=groupsData.find(g=>g.key===adminGroup);if(selected){const rows=selected.items.filter(v=>(adminFilter==='all'||adminFilter==='pending'&&['DRAFT','IN_REVIEW'].includes(v.status)||adminFilter==='published'&&v.status==='PUBLISHED')&&(!adminQuery||v.contentJson.title.toLocaleLowerCase('vi').includes(adminQuery))).sort((a,b)=>adminFilter==='pending'?draftPriority(b.contentJson).score-draftPriority(a.contentJson).score:0);return `<div class="reviewer-heading"><div><span class="rail-kicker">NHÓM CHECKLIST</span><h2>${esc(selected.label)}</h2><p>${selected.pending} cần duyệt · ${selected.published} đã duyệt</p></div>${btn('Tất cả nhóm','admin-groups')}</div><form id="reviewer-filter" class="reviewer-filters"><label>Tìm checklist<input name="query" value="${esc(adminQuery)}" placeholder="Nhập tên công việc…"></label><label>Hiển thị<select name="status"><option value="pending" ${adminFilter==='pending'?'selected':''}>Cần duyệt</option><option value="published" ${adminFilter==='published'?'selected':''}>Đã duyệt</option><option value="all" ${adminFilter==='all'?'selected':''}>Tất cả</option></select></label><button class="secondary-button">Lọc</button></form><div class="reviewer-list">${rows.map(v=>`<article class="reviewer-item"><div><span class="status-badge ${v.status==='PUBLISHED'?'teal':'amber'}">${labels[v.status]}</span><h3>${esc(v.contentJson.title)}</h3><p>${v.contentJson.steps.length} điểm kiểm tra · Phiên bản ${v.version}${['DRAFT','IN_REVIEW'].includes(v.status)?` · <span title="${esc(draftPriority(v.contentJson).reasons.join('; '))}">Ưu tiên duyệt: ${draftPriority(v.contentJson).score}</span>`:''}</p></div>${btn('Kiểm tra checklist','version',v.id)}</article>`).join('')||'<div class="empty-state"><h3>Không có checklist khớp bộ lọc</h3><p>Đổi trạng thái hoặc từ khóa để xem các mục khác.</p></div>'}</div>`;}
return `<div class="panel-actions">${btn('Soạn checklist mới','author-new')}${btn('Nhập văn bản thủ công','source-import')}</div><div class="reviewer-heading"><div><span class="rail-kicker">DUYỆT THEO NHÓM</span><h2>Chọn nhóm cần kiểm tra</h2><p>${groupsData.reduce((n,g)=>n+g.pending,0)} checklist cần duyệt. Mở một nhóm để xem danh sách.</p></div></div><div class="reviewer-group-grid">${groupsData.map(g=>`<button type="button" class="reviewer-group-tile" data-compliance="admin-group" data-id="${g.key}" aria-label="${esc(g.label)}: ${g.pending} checklist cần duyệt"><span>${esc(g.label)}</span><strong>${g.pending}</strong><small>checklist cần duyệt</small><p>${g.items.length} tổng · ${g.published} đã duyệt</p></button>`).join('')}</div>`;}
function renderGuideEditor(c,citations){const g=checklistGuide(c);return `<h3>Nội dung checklist chi tiết</h3>${field('guide-question','Câu hỏi cần làm rõ',g.question)}${area('guide-proof','Hồ sơ / bằng chứng nên lưu nội bộ',g.proof)}${area('guide-done','Điều kiện kết thúc rà soát',g.done)}${field('guide-owner','Người phụ trách gợi ý',g.owner)}${area('guide-timing','Thời điểm rà soát / hướng dẫn mốc nhắc',g.timing)}${g.steps.map((s,i)=>`<details id="guide-edit-${i}"><summary>Chỉnh sửa điểm ${i+1} · ${esc(c.steps[i])}</summary>${area('guide-detail-'+i,'Diễn giải cụ thể',s.detail)}${field('guide-when-'+i,'Chỉ khi (để trống nếu không có điều kiện riêng)',s.when,'text',false)}${area('guide-checks-'+i,'Các nội dung cần đối chiếu — mỗi dòng một nội dung',s.checks.join('\n'))}${area('guide-evidence-'+i,'Bằng chứng cần đối chiếu tại điểm này',s.evidence)}<p>Chọn căn cứ đã xác định liên quan đến điểm này; có thể để trống.</p>${citations.map((c,j)=>`<label class="compliance-check"><input type="checkbox" name="guide-refs-${i}" value="${esc(c.provisionId)}" ${s.provisionIds.includes(c.provisionId)?'checked':''}>Căn cứ ${j+1} · ${esc((c.quote||'').split('\n')[0].slice(0,150))}</label>`).join('')}</details>`).join('')}`;}
function reviewerPreview(c,citations,edit){const g=checklistGuide(c);return `<section class="reviewer-section"><h3>1. Doanh nghiệp cần làm gì?</h3><p>${esc(c.action)}</p><div class="reviewer-facts"><div><strong>Áp dụng khi</strong><p>${esc(ruleText(c.rule))}</p></div><div><strong>Thời hạn</strong><p>${esc(deadlineText(c.deadline))}</p></div></div><details><summary>Ngoại lệ và hiệu lực</summary><p>${esc(c.exceptions)}</p><p>Từ ${esc(c.effectiveFrom)}${c.effectiveUntil?' đến '+esc(c.effectiveUntil):''}</p></details></section><section class="reviewer-section"><h3>2. Các điểm người dùng cần kiểm tra (${c.steps.length})</h3><div class="reviewer-points">${g.steps.map((point,i)=>`<details class="reviewer-point" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(c.steps[i])}</strong></summary>${point.when?`<p><strong>Chỉ khi:</strong> ${esc(point.when)}</p>`:''}<p>${esc(point.detail)}</p><ul>${point.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><strong>Bằng chứng:</strong> ${esc(point.evidence)}</p>${point.provisionIds.map(id=>citations.find(x=>x.provisionId===id)).filter(Boolean).map(cite).join('')}${edit?`<button type="button" class="text-action" data-guide-edit="${i}">Chỉnh sửa điểm này</button>`:''}</details>`).join('')}</div><details><summary>Hồ sơ cần lưu và điều kiện hoàn tất</summary><p><strong>Hồ sơ:</strong> ${esc(g.proof)}</p><p><strong>Hoàn tất khi:</strong> ${esc(g.done)}</p><p><strong>Phụ trách gợi ý:</strong> ${esc(g.owner)}</p><p>${esc(g.timing)}</p></details></section>`;}
function renderEditor(){const {row:v,candidate}=editor,c=v.contentJson,edit=v.status==='DRAFT',citations=v.citations||[],tab=editor.tab||'review',checks={action:'Hành động rõ ràng',scope:'Đúng đối tượng áp dụng',exceptions:'Đủ ngoại lệ',effectiveDates:'Hiệu lực phù hợp',deadline:'Thời hạn đúng',citations:'Căn cứ đã đối chiếu'};const tabs=[['review','Kiểm tra'],...(edit?[['edit','Chỉnh sửa']]:[]),['preview','Xem như doanh nghiệp']];
const header=`<div class="reviewer-heading"><div><span class="rail-kicker">${esc(groups[c.group])} · ${labels[v.status]}</span><h2>${esc(c.title||candidate?.title||'Soạn checklist')}</h2><p>Phiên bản ${v.version||1}</p></div></div><div class="tab-bar reviewer-tabs">${tabs.map(([key,label])=>`<button type="button" class="${tab===key?'active':''}" data-reviewer-tab="${key}" aria-selected="${tab===key}">${label}</button>`).join('')}</div>${editor.dirty?'<p class="info-callout">Có chỉnh sửa chưa lưu. Lưu chỉnh sửa trước khi duyệt.</p>':''}`;
const history=`<details class="reviewer-aux"><summary>Lịch sử và lưu ý bổ sung</summary>${renderReviewNotes(v.id)}${(v.reviews||[]).map(x=>`<p>${x.decision==='APPROVE'?'Đã duyệt':'Trả lại'} · ${esc(x.note)} · ${esc(new Date(x.createdAt).toLocaleString('vi-VN'))}</p>`).join('')||'<p>Chưa có lịch sử duyệt.</p>'}${v.status==='PUBLISHED'?btn('Ngừng phát hành nghĩa vụ này','retire',v.id):''}</details>`;
if(tab==='preview')return header+`<section class="checklist-review-preview" aria-label="Nội dung người dùng sẽ nhận">${renderGuide(c,citations,{review:{steps:[]},readOnly:true,esc,icon:h.icon,cite})}</section>`+history;
if(tab==='edit'){editor.ruleDraft??=structuredClone(c.rule);editor.deadlineDraft??=structuredClone(c.deadline);return header+`<form id="compliance-draft" class="product-form reviewer-edit"><fieldset><section class="reviewer-section"><h3>Thông tin chính</h3>${field('title','Tên checklist',c.title)}${area('action','Doanh nghiệp cần làm gì?',c.action)}<div class="reviewer-facts"><label>Nhóm<select name="group">${Object.entries(groups).map(([k,t])=>`<option value="${k}" ${c.group===k?'selected':''}>${t}</option>`).join('')}</select></label><label>Phạm vi<select name="scope">${Object.entries({COMPANY:'Doanh nghiệp',SITE:'Từng địa điểm',EVENT:'Từng sự kiện'}).map(([k,t])=>`<option value="${k}" ${c.scope===k?'selected':''}>${t}</option>`).join('')}</select></label></div>${area('exceptions','Ngoại lệ / lưu ý',c.exceptions)}</section><details class="reviewer-section" ${editor.isNew?'open':''}><summary>Điều kiện áp dụng và thời hạn</summary><h3>Áp dụng khi</h3>${renderRuleBuilder(editor.ruleDraft,esc)}${editor.ruleDraft.all||editor.ruleDraft.any?'':'<button type="button" class="secondary-button" data-rule-add="root">Thêm điều kiện áp dụng</button>'}<h3>Thời hạn</h3>${renderDeadlineBuilder(editor.deadlineDraft,esc)}<div class="reviewer-facts">${field('effectiveFrom','Áp dụng từ',c.effectiveFrom,'date')}${field('effectiveUntil','Đến ngày (nếu có)',c.effectiveUntil,'date',false)}</div></details><details class="reviewer-section" id="reviewer-edit-points" ${editor.isNew?'open':''}><summary>Nội dung các điểm kiểm tra và bằng chứng</summary>${area('steps','Tên các điểm — mỗi dòng một điểm',c.steps.join('\n'))}${renderGuideEditor(c,citations)}<label class="compliance-check"><input type="checkbox" name="evidenceRequired" ${c.evidenceRequired?'checked':''}>Yêu cầu tệp bằng chứng khi hoàn tất</label>${area('evidenceInstructions','Hướng dẫn hồ sơ / bằng chứng',c.evidenceInstructions)}</details>${renderSourceEditor(citations)}<div class="reviewer-save"><button class="primary-button" ${busy?'disabled':''}>${candidate||editor.isNew?'Lưu checklist nháp':'Lưu chỉnh sửa'}</button></div></fieldset></form>`;}
const approve=['DRAFT','IN_REVIEW'].includes(v.status)&&!candidate&&!editor.isNew;
return header+reviewerPreview(c,citations,edit)+`<section class="reviewer-section"><h3>3. Căn cứ và quyết định duyệt</h3>${approve?`<form id="compliance-review" class="product-form">${citations.map((x,i)=>`<div class="reviewer-source">${cite(x)}<label class="compliance-check"><input type="checkbox" name="ocr-${i}" ${x.ocrVerified?'checked':''}>Đã đối chiếu nguyên văn căn cứ ${i+1}</label></div>`).join('')}<div class="reviewer-confirmations">${Object.entries(checks).map(([k,t])=>`<label class="compliance-check"><input type="checkbox" name="${k}">${t}</label>`).join('')}</div>${area('note','Nhận xét khi duyệt (không bắt buộc) / lý do trả lại (ít nhất 3 ký tự)','',false)}<div class="reviewer-save"><button name="decision" value="APPROVE" class="primary-button" ${busy||editor.dirty?'disabled':''}>Duyệt và đưa đến người dùng</button><button name="decision" value="REJECT" class="secondary-button" ${busy||editor.dirty?'disabled':''}>Trả lại để chỉnh sửa</button></div></form>`:citations.map(cite).join('')}${['PUBLISHED','RETIRED'].includes(v.status)?btn('Tạo phiên bản mới để chỉnh sửa','new-version',v.id):''}</section>`+history;
}
function taskVerification(t){return renderVerificationForm(t.verification,{esc,disabled:busy||!h.canEdit()});}
function renderTask(t){const c=t.basis.contentJson;if(summaryOnly(t,false))return renderVerificationSummary(c,t.basis.citations,{missingFacts:t.missingFacts.map(factLabel),explanation:t.explanation,verificationHtml:taskVerification(t),esc,icon:h.icon,cite});const r=detailReview(t,false);return `${t.verification?.questions?.length?taskVerification(t):''}<p>${labels[t.status]} · ${labels[t.applicability]} · ${esc(periodLabel(t.periodKey))}</p><p>${esc(t.explanation)}</p>${t.missingFacts.length?`<div class="info-callout">Cần bổ sung: ${t.missingFacts.map(x=>esc(factLabel(x))).join(', ')}. Checklist tự cập nhật sau khi lưu hồ sơ.</div>`:''}<dl class="task-dates"><div><dt>${DATE_LABELS.LEGAL}</dt><dd>${esc(vnDate(t.legalDueDate||(t.dueDateKind==='LEGAL'?t.dueDate:''))||'Chưa xác định')}</dd><small>Theo căn cứ đã duyệt</small></div><div><dt>${DATE_LABELS.EXPECTED}</dt><dd>${esc(vnDate(t.dueDateKind==='USER'?t.dueDate:'')||'Chưa đặt')}</dd><small>Mốc nội bộ của doanh nghiệp</small></div><div><dt>${DATE_LABELS.REMINDER}</dt><dd>${esc(vnDate(t.reviewJson?.reminderDate)||'Chưa đặt')}</dd><small>LIMI nhắc vào ngày này</small></div></dl>${basisNotice(t)}<form id="compliance-task" class="product-form"><fieldset ${!h.canEdit()?'disabled':''}>${renderGuide(c,t.basis.citations,{review:r,openGroups:detail.openGroups,controls:reviewControls(t,false),ownerControls:`<label>Người phụ trách<select name="assigneeId"><option value="">Chưa giao</option>${t.members.map(m=>`<option value="${m.id}" ${m.id===(detail.draftAssignee??t.assigneeId)?'selected':''}>${esc(m.name)} · ${esc(m.email)}</option>`).join('')}</select></label><div class="task-date-fields">${field('dueDate',DATE_LABELS.EXPECTED,detail.draftDueDate??(t.dueDateKind==='USER'?t.dueDate?.slice(0,10):''),'date',false)}${field('reminderDate',DATE_LABELS.REMINDER,r.reminderDate||'','date',false)}</div>`,readOnly:!h.canEdit()||t.applicability!=='APPLY',esc,icon:h.icon,cite})}${field('note','Ghi chú thay đổi',detail.draftNote||'','text',false)}<button class="primary-button" ${busy?'disabled':''}>Lưu kết quả rà soát</button></fieldset></form><div class="sheet-section"><h3>Tệp bằng chứng</h3><p>${c.evidenceRequired?'Bộ nghĩa vụ yêu cầu tải lên ít nhất một tệp bằng chứng trước khi kết thúc.':'Không bắt buộc. Tải lên nếu muốn lưu bản sao cùng công việc.'}</p>${t.evidence.map(e=>`<div class="product-row"><span>${esc(e.filename)} · ${labels[e.state]||esc(e.state)}${e.basisVersionId!==t.basisVersionId?' · Căn cứ cũ (lưu lịch sử)':''}</span>${e.state==='AVAILABLE'?btn('Tải xuống','download',e.id):e.state==='UPLOADED'&&h.canEdit()?btn('Kiểm tra và hoàn tất','complete',e.id):''}</div>`).join('')}${h.canEdit()?`<form id="compliance-upload" class="product-form"><label>Tệp bằng chứng (tối đa 10 MB)<input type="file" name="file" required accept=".pdf,.png,.jpg,.jpeg,.txt,.docx"></label><button class="primary-button" ${busy?'disabled':''}>Tải lên và kiểm tra</button><p class="field-hint">Tệp lưu trong kho riêng; chỉ thành viên có quyền mới tải xuống.</p></form>`:''}</div><details class="sheet-section"><summary>Lịch sử công việc</summary>${t.history.map(x=>`<p>${esc(new Date(x.createdAt).toLocaleString('vi-VN'))} · ${esc(x.action)}<br>${esc(x.note)}</p>`).join('')}</details>`;}
function renderEvaluation(e){return `<h2>Kết quả đánh giá ${esc(e.asOfDate.slice(0,10))}</h2><p>${labels[e.status]} · ${esc(e.release.name)} · ${esc(e.engineVersion)}</p><p>Hồ sơ và bộ nghĩa vụ được cố định cho lần đánh giá này.</p>${e.decisions.map(d=>`<details><summary>${esc(d.version.contentJson.title)} · ${labels[d.decision]}</summary><p>${esc(d.explanation)}</p><p>Cần bổ sung: ${d.missingFacts.map(esc).join(', ')||'Không có'}</p><p>Hạn: ${esc(d.dueDate?.slice(0,10)||'Chưa xác định')}</p>${d.version.citations.map(cite).join('')}</details>`).join('')}`;}
function basisNotice(t){const v=t.basisCandidate;if(!v)return '';return `<div class="info-callout"><h3>Cần xem lại căn cứ mới · v${v.version}</h3><p>${esc(v.contentJson.action)}</p>${v.citations.map(cite).join('')}<p>Việc đã hoàn thành và bằng chứng cũ được giữ trong lịch sử. Nếu nhận căn cứ mới, công việc trở về Cần làm và các bước được kiểm tra lại.</p>${h.canEdit()?`<form id="compliance-basis" class="product-form">${field('note','Lý do tiếp nhận căn cứ mới')}${['DONE','NOT_APPLICABLE'].includes(t.status)?'<label class="compliance-check"><input type="checkbox" name="reopen" required>Tôi xác nhận mở lại công việc đã hoàn thành</label>':''}<button class="primary-button" ${busy?'disabled':''}>Tiếp nhận căn cứ mới</button></form>`:''}</div>`;}
async function openVersion(id){const [row,imports]=await Promise.all([h.api('/admin/obligations/'+id),h.api('/admin/checklist-imports?versionId='+encodeURIComponent(id))]);editor={row,tab:'review'};data.imports=imports.items;detail=null;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-compliance]');if(!b||!h)return;const action=b.dataset.compliance,id=b.dataset.id;if(action==='back'&&detail&&['task','pilot'].includes(detail.type)){detail=null;error='';h.render();window.scrollTo({top:listScroll});return;}void run(async()=>{
 if(action==='source-import'){sourceImport=true;editor=null;}
 if(action==='author-new'){editor={tab:'edit',isNew:true,row:{status:'DRAFT',citations:[],contentJson:{title:'',action:'',group:'company',scope:'COMPANY',rule:{fact:'stage',op:'eq',value:'running'},exceptions:'',effectiveFrom:'',effectiveUntil:null,deadline:{kind:'NONE'},steps:[''],evidenceRequired:false,evidenceInstructions:''}}};}
 if(action==='source-find'){const q=document.querySelector('[name=source-query]')?.value||'';editor.sources=await h.api('/admin/legal-sources?q='+encodeURIComponent(q));editor.sourceDocument=null;editor.sourcePage=0;}
 if(action==='source-document'){editor.sourceDocument=id;editor.sourcePage=0;editor.sources=await h.api('/admin/legal-sources?documentId='+encodeURIComponent(id));}
 if(action==='source-page'){editor.sourcePage=Math.max(0,(editor.sourcePage||0)+Number(id));editor.sources=await h.api('/admin/legal-sources?page='+editor.sourcePage+(editor.sourceDocument?'&documentId='+encodeURIComponent(editor.sourceDocument):'&q='+encodeURIComponent(document.querySelector('[name=source-query]')?.value||'')));}
 if(action==='source-add'){const c=editor.sources.items.find(x=>x.provisionId===id);if(c&&!editor.row.citations.some(x=>x.provisionId===id)){if(editor.row.citations.length>=10)throw Error('Mỗi checklist tối đa 10 căn cứ.');editor.row.citations.push(c);editor.dirty=true;}}
 if(action==='source-remove'){editor.row.citations=editor.row.citations.filter(c=>c.provisionId!==id);editor.dirty=true;}
 if(action==='admin-group'){adminGroup=id;adminFilter='pending';adminQuery='';}
 if(action==='admin-groups'){adminGroup=null;}
 if(action==='refresh'){detail=null;editor=null;await refresh(h.screen());}
 if(action==='back'){sourceImport=false;detail=null;editor=null;await refresh(h.screen());}
 if(action==='next'||action==='previous'){page+=action==='next'?1:-1;if(h.screen()==='checklist')saveView();await refresh(h.screen());window.scrollTo({top:0});}
 if(action==='mode'){mode=id;filter='all';page=0;detail=null;await refresh(h.screen());}
 if(action==='filter'){filter=id;page=0;if(h.screen()==='checklist')saveView();if(mode==='official')await refresh(h.screen());}
 if(action==='calendar'){calendarOffset+=Number(id);}
 if(action==='calendar-reset')calendarOffset=0;
 if(action==='calendar-toggle')calendarOpen=!(document.querySelector('.compliance-calendar')&&!document.querySelector('.compliance-calendar.collapsed'));
 if(action==='pilot')detail={type:'pilot',row:data.preview.items.find(x=>x.versionId===id)};
 if(action==='report'){captureReview(document.querySelector('#compliance-task'));h.openFeedback(detail.row);return;}
 if(action==='task'){listScroll=window.scrollY;detail={type:'task',row:await h.api('/tasks/'+id)};}
 if(action==='evaluation')detail={type:'evaluation',row:await h.api('/evaluations/'+id)};
 if(action==='retry-evaluation'){await h.api('/evaluations/'+id+'/retry','POST',{});await refresh(h.screen());}
 if(action==='version')await openVersion(id);
 if(action==='candidate'){const c=data.candidates.items.find(c=>c.id===id);editor={tab:'edit',candidate:c,row:{status:'DRAFT',citations:[{documentId:c.documentId,snapshotId:c.snapshotId,parseRunId:c.parseRunId,provisionId:c.provisionId,quote:c.excerpt,ocrVerified:false}],contentJson:{title:'',action:'',group:groups[c.groupCode]?c.groupCode:'company',scope:'COMPANY',rule:{fact:'stage',op:'eq',value:'running'},exceptions:'',effectiveFrom:'',effectiveUntil:null,deadline:{kind:'NONE'},steps:[''],evidenceRequired:true,evidenceInstructions:''}}};}
 if(action==='submit'){await h.api('/admin/obligations/'+id+'/submit','POST',{expectedRevision:editor.row.revision});await openVersion(id);}
 if(action==='new-version'){const v=await h.api('/admin/obligations/'+id+'/new-version','POST',{});await openVersion(v.id);}
 if(action==='retire'){await h.api('/admin/obligations/'+id+'/retire','POST',{});await openVersion(id);}
 if(action==='complete'){await h.api('/evidence/'+id+'/complete','POST',{});detail.row=await h.api('/tasks/'+detail.row.id);}
 if(action==='download'){const link=await h.api('/evidence/'+id+'/link');const a=document.createElement('a');a.href=window.LIMI_WORKSPACE_API+link.url;a.download='';document.body.append(a);a.click();a.remove();}
});});
document.addEventListener('submit',e=>{const form=e.target;if(form.id==='compliance-decision'||!form.id?.startsWith('compliance-')||!h)return;e.preventDefault();const fd=new FormData(form),v=Object.fromEntries(fd),decision=e.submitter?.value;void run(async()=>{
 if(form.id==='compliance-evaluate'){assessmentDates.set(h.company().id,v.asOfDate);if(mode==='pilot'){await h.api(`/companies/${h.company().id}/evaluations/preview`,'POST',{asOfDate:v.asOfDate});await refresh(h.screen());data.preview=await h.api(`/companies/${h.company().id}/checklist-preview?asOfDate=${encodeURIComponent(v.asOfDate)}`);}else{await h.api(`/companies/${h.company().id}/evaluations`,'POST',{asOfDate:v.asOfDate});await refresh(h.screen());}}
 if(form.id==='compliance-source-import'){await h.api('/admin/legal-sources','POST',v);sourceImport=false;await refresh('admin');notify('Đã lưu văn bản chờ đối chiếu. Chọn Soạn checklist mới để gắn căn cứ.');}
 if(form.id==='compliance-filter'){query=v.query.trim().toLocaleLowerCase('vi');group=v.group;sort=['due','title','recent'].includes(v.sort)?v.sort:'due';page=0;saveView();if(mode==='official')await refresh(h.screen());}
 if(form.id==='compliance-pilot'){const t=detail.row,companyId=h.company().id;captureReview(form);const review=detail.draftReview;await h.api(`/companies/${h.company().id}/pilot-checklist/${t.versionId}`,'PATCH',{expectedRevision:t.progress.revision,basisHash:t.basisHash,asOfDate:data.preview.asOfDate,status:v.status,steps:review.steps.filter(s=>s.result!=='issue').map(s=>s.index),review,note:v.note});if(detail?.row?.versionId!==t.versionId)return;await refresh(h.screen());if(detail?.row?.versionId!==t.versionId)return;detail.row=data.preview.items.find(x=>x.versionId===t.versionId);delete detail.draftReview;delete detail.draftStatus;delete detail.draftNote;delete detail.draftWorkDeadline;detail.editingDeadline=false;}
 if(form.id==='compliance-release'){if(v.name.trim().length<3)throw Error('Tên bộ phát hành cần ít nhất 3 ký tự.');if(!fd.getAll('versions').length)throw Error('Chọn ít nhất một checklist đã duyệt để phát hành.');await h.api('/admin/releases','POST',{name:v.name,versionIds:fd.getAll('versions')});await refresh('admin');}
 if(form.id==='compliance-draft'){const content={title:v.title,action:v.action,group:v.group,scope:v.scope,rule:readRule(editor.ruleDraft,fd),exceptions:v.exceptions,effectiveFrom:v.effectiveFrom,effectiveUntil:v.effectiveUntil||null,deadline:readDeadline(fd),steps:v.steps.split('\n').map(s=>s.trim()).filter(Boolean),evidenceRequired:fd.has('evidenceRequired'),evidenceInstructions:v.evidenceInstructions};const fallback=checklistGuide(content);content.guide={question:v['guide-question']||fallback.question,proof:v['guide-proof']||fallback.proof,done:v['guide-done']||fallback.done,owner:v['guide-owner']||fallback.owner,timing:v['guide-timing']||fallback.timing,steps:content.steps.map((s,i)=>({detail:v['guide-detail-'+i]||s,when:v['guide-when-'+i]||'',checks:(v['guide-checks-'+i]||s).split('\n').map(x=>x.trim()).filter(Boolean),evidence:v['guide-evidence-'+i]||content.evidenceInstructions,provisionIds:fd.getAll('guide-refs-'+i)}))};const citations=editor.row.citations.map((c,i)=>({documentId:c.documentId,snapshotId:c.snapshotId,parseRunId:c.parseRunId,provisionId:c.provisionId,ocrVerified:c.ocrVerified||fd.has('ocr-'+i)}));const result=await h.api(editor.candidate?`/admin/candidates/${editor.candidate.id}/draft`:editor.isNew?'/admin/obligations':`/admin/obligations/${editor.row.id}`,editor.candidate||editor.isNew?'POST':'PUT',{content,citations,...(editor.candidate||editor.isNew?{}:{expectedRevision:editor.row.revision})});await openVersion(result.id);}
 if(form.id==='compliance-review'){let row=editor.row;const checks=Object.fromEntries(['action','scope','exceptions','effectiveDates','deadline','citations'].map(k=>[k,fd.has(k)]));if(decision==='APPROVE'&&Object.values(checks).some(x=>!x))throw Error('Xác nhận đủ 6 nội dung đã kiểm tra trước khi duyệt.');if(decision==='REJECT'&&v.note.trim().length<3)throw Error('Ghi lý do trả lại ít nhất 3 ký tự.');try{if(row.status==='DRAFT')row=await h.api('/admin/obligations/'+row.id+'/submit','POST',{expectedRevision:row.revision});const verifiedCitationIds=decision==='APPROVE'?editor.row.citations.flatMap((c,i)=>fd.has('ocr-'+i)?[c.id]:[]):[];await h.api('/admin/obligations/'+row.id+'/review','POST',{decision,expectedRevision:row.revision,note:v.note,checks,verifiedCitationIds});await openVersion(row.id);}catch(e){await openVersion(row.id);throw e;}}
 if(form.id==='compliance-basis'){const t=detail.row;await h.api('/tasks/'+t.id+'/adopt-basis','POST',{expectedRevision:t.revision,decisionId:t.basisCandidate.decisionId,reopen:fd.has('reopen'),note:v.note});detail.row=await h.api('/tasks/'+t.id);delete detail.draftReview;delete detail.draftStatus;}
 if(form.id==='compliance-task'){captureReview(form);const t=detail.row,review=detail.draftReview,input={expectedRevision:t.revision,status:v.status,assigneeId:v.assigneeId||null,steps:review.steps.filter(s=>s.result!=='issue').map(s=>s.index),review,note:v.note};if(v.dueDate||t.dueDateKind==='USER')input.dueDate=v.dueDate||null;await h.api('/tasks/'+t.id,'PATCH',input);if(detail?.row?.id!==t.id)return;const updated=await h.api('/tasks/'+t.id);if(detail?.row?.id!==t.id)return;detail.row=updated;await refresh(h.screen());if(detail?.row?.id!==t.id)return;delete detail.draftReview;delete detail.draftStatus;delete detail.draftDueDate;delete detail.draftAssignee;delete detail.draftWorkDeadline;detail.editingDeadline=false;}
 if(form.id==='compliance-upload'){const file=fd.get('file');if(!file?.size||file.size>10*1024*1024)throw Error('Chọn tệp có dung lượng từ 1 byte đến 10 MB.');const bytes=await file.arrayBuffer(),digest=await crypto.subtle.digest('SHA-256',bytes),checksum=[...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');const types={pdf:'application/pdf',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',txt:'text/plain',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'},mimeType=types[file.name.split('.').pop().toLowerCase()];if(!mimeType)throw Error('Chọn PDF, PNG, JPG, TXT hoặc DOCX.');const g=await h.api('/tasks/'+detail.row.id+'/evidence/init','POST',{filename:file.name,mimeType,sizeBytes:file.size,checksum});const response=await fetch(window.LIMI_WORKSPACE_API+g.uploadUrl,{method:'PUT',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-CSRF-Token':h.csrf(),'X-Upload-Token':g.uploadToken},body:bytes,signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('Tải tệp chưa thành công. Hãy chọn và tải lại tệp; chưa ghi nhận bằng chứng hoàn tất.');await h.api('/evidence/'+g.id+'/complete','POST',{});detail.row=await h.api('/tasks/'+detail.row.id);}
});});



function renderCoverage(){
 const c=data?.coverage;if(!c)return '';
 const states={CITED_BY_DRAFTS:'Có checklist gắn căn cứ',SANCTIONS_REFERENCE:'Đối chiếu chế tài',AMENDMENT_DEPENDENCY:'Đối chiếu sửa đổi',JURISDICTION_REFERENCE:'Phạm vi / phối hợp địa phương',SUPPORTING_REFERENCE:'Nguồn hướng dẫn',AWAITING_IMPORT:'Chưa nhập checklist'};
 return `<details class="verification-brief" id="checklist-source-coverage"><summary>Đối chiếu nguồn luật: ${c.availableDocuments} văn bản · ${c.importedChecklists} checklist đã nhập</summary><p>${esc(c.notice)}</p>${c.documents.map(d=>`<section class="compliance-candidate"><h3>${esc(d.documentNumber)} · ${esc(d.title)}</h3><p>${esc(groups[d.group]||d.group)} · ${esc(states[d.status]||d.status)} · ${d.linkedDrafts.length} mục gắn trực tiếp</p><p>${esc(d.reason)}</p><p>Hiệu lực và chuỗi sửa đổi: cần chuyên gia xác nhận.</p>${d.linkedDrafts.length?`<ul>${d.linkedDrafts.map(v=>`<li>${esc(v.title)}</li>`).join('')}</ul>`:''}${d.sources.filter(s=>/^https:\/\//.test(s.url)).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${s.sourceKind==='OFFICIAL'?'Nguồn cơ quan nhà nước':'Nguồn nội dung'} · ${esc(s.domain)}</a>`).join(' · ')}</section>`).join('')}</details>`;
}

function rememberEditor(){const form=document.querySelector('#compliance-draft');if(!form)return;editor.ruleDraft=readRule(editor.ruleDraft,new FormData(form));editor.deadlineDraft=readDeadline(new FormData(form));editor.savedDrafts=captureFormDrafts();editor.editView=captureView();}
function redrawEditor(skipBuilders=false){const drafts=captureFormDrafts();if(skipBuilders)for(const form of drafts.forms)form.fields=form.fields.filter(f=>!f.name.startsWith('rule-')&&!f.name.startsWith('deadline-'));editor.savedDrafts=drafts;h.render();restoreFormDrafts(drafts);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-reviewer-tab],[data-rule-add],[data-rule-remove]');if(!b||!editor||busy)return;if(b.dataset.reviewerTab){if(editor.tab==='edit')rememberEditor();editor.tab=b.dataset.reviewerTab;h.render();if(editor.tab==='edit'&&editor.savedDrafts){restoreFormDrafts(editor.savedDrafts);if(editor.editView)restoreView(editor.editView);}document.querySelector('.reviewer-heading')?.scrollIntoView({block:'start'});return;}const form=document.querySelector('#compliance-draft');if(!form)return;editor.deadlineDraft=readDeadline(new FormData(form));editor.ruleDraft=readRule(editor.ruleDraft,new FormData(form));editor.ruleDraft=alterRule(editor.ruleDraft,b.dataset.ruleAdd??b.dataset.ruleRemove,b.hasAttribute('data-rule-remove')?'remove':'add');editor.dirty=true;redrawEditor(true);});
document.addEventListener('change',e=>{const form=e.target.closest('#compliance-draft');if(!form||!editor)return;editor.dirty=true;if(e.target.hasAttribute('data-rule-change')){editor.deadlineDraft=readDeadline(new FormData(form));editor.ruleDraft=readRule(editor.ruleDraft,new FormData(form));redrawEditor(true);}if(e.target.hasAttribute('data-deadline-change')){editor.ruleDraft=readRule(editor.ruleDraft,new FormData(form));editor.deadlineDraft={kind:e.target.value};redrawEditor(true);}});
document.addEventListener('input',e=>{if(e.target.closest('#compliance-draft')&&editor)editor.dirty=true;});
document.addEventListener('submit',e=>{if(e.target.id!=='reviewer-filter')return;e.preventDefault();const fd=new FormData(e.target);adminFilter=String(fd.get('status'));adminQuery=String(fd.get('query')).trim().toLocaleLowerCase('vi');h.render();});
document.addEventListener('invalid',e=>{if(!e.target.closest('#compliance-draft'))return;let parent=e.target.parentElement;while(parent){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}},true);

function renderSourceEditor(citations){const source=editor.sources;return `<details class="reviewer-section"><summary>Căn cứ nguồn · ${citations.length}/10</summary><p>Chọn đúng văn bản và điều khoản. Bổ sung căn cứ mới tại đây khi sửa checklist theo luật mới.</p>${citations.map(c=>`<div class="reviewer-source">${cite(c)}${btn('Bỏ căn cứ này','source-remove',c.provisionId)}</div>`).join('')}<label>Tìm văn bản<input name="source-query" placeholder="Số hiệu hoặc tên văn bản"></label>${btn('Tìm trong thư viện','source-find')}${source?`<div class="reviewer-list">${source.items.map(x=>x.provisionId?`<article class="reviewer-item"><div><h3>${esc(x.provision.heading||'Điều khoản')}</h3><p>${esc(x.quote.slice(0,350))}…</p></div>${btn('Thêm căn cứ','source-add',x.provisionId)}</article>`:`<article class="reviewer-item"><div><h3>${esc(x.documentNumber)}</h3><p>${esc(x.title)}</p></div>${btn('Chọn điều khoản','source-document',x.id)}</article>`).join('')||'<p>Không có kết quả. Có thể nhập văn bản thủ công từ danh sách nhóm.</p>'}</div><div class="panel-actions">${editor.sourcePage>0?btn('Trước','source-page','-1'):''}<span>Trang ${(editor.sourcePage||0)+1}</span>${((editor.sourcePage||0)+1)*(editor.sourceDocument?10:20)<source.total?btn('Sau','source-page','1'):''}</div>`:''}</details>`;}
function renderSourceImport(){return `<h2>Nhập văn bản từ nguồn chính thức</h2><p>Dán toàn văn đã lấy từ bản gốc. Nội dung được lưu ở trạng thái chờ đối chiếu; người duyệt phải kiểm tra trước khi dùng làm căn cứ. Chức năng này không bật crawl.</p><form id="compliance-source-import" class="product-form">${field('documentNumber','Số hiệu văn bản')}${field('title','Tên văn bản')}${field('issuingBody','Cơ quan ban hành')}${field('sourceUrl','Đường dẫn bản gốc','','url')}<label>Nhóm<select name="group">${Object.entries(groups).map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select></label>${area('fullText','Toàn văn (tối đa 300.000 ký tự)','')}<button class="primary-button" ${busy?'disabled':''}>Lưu văn bản chờ đối chiếu</button></form>`;}
